                </View>
                <Label muted>
                  {formatDate(row.createdAt)} · {row.goals.join(", ")}
                </Label>
                <Label>
                  {row.email} · {row.phone}
                </Label>
                <View style={[s.row, { marginTop: 14 }]}>
                  <Button
                    variant="secondary"
                    onPress={() =>
                      void action(async () =>
