{"behavior":[{"confidence":"observed","description":"Contém JSX que referencia Button, Card, Choices, Confirm, Label, SaveForm, TextFields, View, WorkoutEditor; a execução visual não foi testada.","evidence":[{"end_line":217,"snippet":"export function PlanForm({
  studentId,
  plan,
  done,
  cancel,
}: {
  studentId: string;
  plan?: Plan;
  done: () => void;
  cancel: () => void;
}) {
  const [data, setData] = useState<PlanData>(
    plan ?? {
      title: "",
      objective: "Adaptação",
      difficulty: "Iniciante",
      startsAt: today(),
      endsAt: null,
      instructions: "",
      status: "rascunho",
      workouts: [],
    },
  );
  const [open, setOpen] = useState<number | null>(null);
  const [remove, setRemove] = useState<number | null>(null);
  const [pending, setPending] = useState(false);
  return (
    <SaveForm
      label="Salvar plano"
      cancel={cancel}
      save={async () => {
        if (pending)
          throw new Error(
            "Confirme ou cancele a prescrição aberta antes de salvar.",
          );
        const parsed = planSchema.safeParse(data);
        if (!parsed.success)
          throw new Error(
            parsed.error.issues
              .map((i) => `${i.path.join(".")}: ${i.message}`)
              .join(" · "),
          );
        await api(
          plan
            ? `/workout-plans/${plan.id}`
            : `/students/${studentId}/workout-plans`,
          plan ? "PUT" : "POST",
          parsed.data,
        );
        done();
      }}
    >
      <TextFields
        value={data}
        change={setData}
        fields={[
          ["title", "Nome do plano *"],
          ["objective", "Objetivo *"],
          ["startsAt", "Data de início (AAAA-MM-DD) *"],
          ["endsAt", "Data de término (AAAA-MM-DD)"],
          ["instructions", "Orientações gerais"],
        ]}
      />
      <Choices
        label="Dificuldade"
        value={data.difficulty}
        onChange={(v) =>
          setData({ ...data, difficulty: v as PlanData["difficulty"] })
        }
        options={["Iniciante", "Intermediário", "Avançado"].map((value) => ({
          value,
          label: value,
        }))}
      />
      <Choices
        label="Status do plano"
        value={data.status}
        onChange={(v) => setData({ ...data, status: v as PlanData["status"] })}
        options={(plan?.publishedAt
          ? ["ativo", "arquivado"]
          : ["rascunho", "ativo", "arquivado"]
        ).map((value) => ({ value, label: value }))}
      />
      <Label muted>
        Ao salvar como ativo, o plano será disponibilizado à conta vinculada
        deste aluno. Todas as alterações abaixo são salvas juntas.
      </Label>
      {!data.workouts.length && (
        <Label>Este plano ainda não possui treinos.</Label>
      )}
      {data.workouts.map((w, index) => (
        <Card key={w.id ?? `new-${index}`}>
          <Label size={20} bold>
            {index + 1}. {w.name || "Novo treino"}
          </Label>
          <View style={s.row}>
            <Button
              disabled={pending}
              variant="secondary"
              onPress={() => setOpen(open === index ? null : index)}
            >
              {open === index ? "Recolher treino" : "Editar treino"}
            </Button>
            <Button
              disabled={pending}
              variant="secondary"
              onPress={() => {
                const copy = {
                  ...w,
                  id: undefined,
                  name: `${w.name} (cópia)`,
                  exercises: w.exercises.map((e) => ({ ...e, id: undefined })),
                };
                setData({ ...data, workouts: [...data.workouts, copy] });
                setOpen(data.workouts.length);
              }}
            >
              Duplicar treino
            </Button>
            <Button
              label={`Subir treino ${index + 1}`}
              disabled={pending || index === 0}
              variant="secondary"
              onPress={() => {
                setData({ ...data, workouts: move(data.workouts, index, -1) });
                setOpen(null);
              }}
            >
              ↑
            </Button>
            <Button
              label={`Descer treino ${index + 1}`}
              disabled={pending || index === data.workouts.length - 1}
              variant="secondary"
              onPress={() => {
                setData({ ...data, workouts: move(data.workouts, index, 1) });
                setOpen(null);
              }}
            >
              ↓
            </Button>
            <Button
              disabled={pending}
              variant="danger"
              onPress={() => setRemove(index)}
            >
