              </Button>
              {expanded === r.id &&
                (r.data.criteria as Criterion[]).map((c) => (
                  <Card key={c.criterion}>
                    <Label bold>{c.criterion}</Label>
                    {[
                      ["Observação / medida", c.observation],
                      ["Inicial", c.initial],
                      ["Atual", c.current],
                      ["Próxima ação", c.nextAction],
                    ].map(([label, value]) => (
                      <View key={label} style={{ marginTop: 8 }}>
                        <Label size={11} muted>
                          {label}
                        </Label>
                        <Label>{value || "—"}</Label>
                      </View>
                    ))}
                  </Card>
