export function Button({
  children,
  onPress,
  variant = "primary",
  disabled = false,
  label,
}: {
  children: ReactNode;
  onPress: () => void;
  variant?: "primary" | "secondary" | "danger";
  disabled?: boolean;
  label?: string;
}) {
  const t = useTheme();
  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={
        label ?? (typeof children === "string" ? children : undefined)
      }
      disabled={disabled}
      onPress={onPress}
      style={({ pressed }) => [
        s.button,
        {
          backgroundColor:
            variant === "primary"
              ? t.accent
              : variant === "danger"
                ? t.accentSoft
                : t.backgroundElement,
          borderColor: variant === "primary" ? t.accent : t.border,
          opacity: disabled ? 0.45 : pressed ? 0.75 : 1,
