    >
      <Text
        style={{
          fontFamily: Fonts.sans,
          fontWeight: "600",
          fontSize: 13,
          color:
            variant === "primary"
              ? "#fff"
              : variant === "danger"
                ? t.danger
                : t.text,
        }}
      >
        {children}
      </Text>
    </Pressable>
  );
}

